// Crée une date correspondant à maintenant.
const now = new Date()

// Crée une copie de la date actuelle.
const tomorrow = new Date(now)

// Ajoute un jour pour obtenir la date de demain.
tomorrow.setDate(now.getDate() + 1)

// Crée une fonction qui transforme une date au format Gmail.
function formatForGmail(date) {
  // Récupère l'année.
  const year = date.getFullYear()

  // Récupère le mois avec deux chiffres.
  const month = String(date.getMonth() + 1).padStart(2, '0')

  // Récupère le jour avec deux chiffres.
  const day = String(date.getDate()).padStart(2, '0')

  // Retourne la date au format attendu par Gmail.
  return `${year}/${month}/${day}`
}

// Crée une fonction qui transforme une date au format React.
function formatForReact(date) {
  // Récupère l'année.
  const year = date.getFullYear()

  // Récupère le mois avec deux chiffres.
  const month = String(date.getMonth() + 1).padStart(2, '0')

  // Récupère le jour avec deux chiffres.
  const day = String(date.getDate()).padStart(2, '0')

  // Retourne la date au format simple.
  return `${year}-${month}-${day}`
}

// Prépare la date du jour pour Gmail.
const todayForGmail = formatForGmail(now)

// Prépare la date de demain pour Gmail.
const tomorrowForGmail = formatForGmail(tomorrow)

// Prépare la date du jour pour React.
const todayForReact = formatForReact(now)

// Prépare la recherche Gmail des mails reçus aujourd'hui.
const searchQuery = `in:inbox after:${todayForGmail} before:${tomorrowForGmail}`

// Retourne les données au nœud suivant.
return [
  {
    json: {
      today: todayForReact,
      searchQuery: searchQuery
    }
  }
]

// Récupère tous les e-mails reçus depuis le nœud Gmail précédent.
const items = $input.all()

// Transforme une valeur quelconque en texte simple.
function toText(value) {
  // Vérifie si la valeur est absente.
  if (value === undefined || value === null) {
    // Retourne un texte vide.
    return ''
  }

  // Vérifie si la valeur est déjà un texte.
  if (typeof value === 'string') {
    // Retourne directement le texte.
    return value
  }

  // Vérifie si la valeur est un nombre.
  if (typeof value === 'number') {
    // Convertit le nombre en texte.
    return String(value)
  }

  // Vérifie si la valeur est un tableau.
  if (Array.isArray(value)) {
    // Convertit chaque élément du tableau en texte.
    return value.map((item) => toText(item)).filter(Boolean).join(', ')
  }

  // Vérifie si la valeur est un objet.
  if (typeof value === 'object') {
    // Vérifie si l'objet contient un nom et une adresse e-mail.
    if (value.name && value.email) {
      // Retourne le nom et l'adresse.
      return `${value.name} <${value.email}>`
    }

    // Vérifie si l'objet contient un nom et une adresse.
    if (value.name && value.address) {
      // Retourne le nom et l'adresse.
      return `${value.name} <${value.address}>`
    }

    // Vérifie si l'objet contient une valeur textuelle.
    if (value.text) {
      // Retourne le texte.
      return toText(value.text)
    }

    // Vérifie si l'objet contient une valeur HTML.
    if (value.html) {
      // Retourne le HTML.
      return toText(value.html)
    }

    // Vérifie si l'objet contient une valeur.
    if (value.value) {
      // Retourne la valeur.
      return toText(value.value)
    }

    // Vérifie si l'objet contient une adresse e-mail.
    if (value.email) {
      // Retourne l'adresse e-mail.
      return toText(value.email)
    }

    // Vérifie si l'objet contient une adresse.
    if (value.address) {
      // Retourne l'adresse.
      return toText(value.address)
    }

    // Vérifie si l'objet contient un body.
    if (value.body) {
      // Retourne le body.
      return toText(value.body)
    }

    // Vérifie si l'objet contient des données.
    if (value.data) {
      // Retourne les données.
      return toText(value.data)
    }
  }

  // Retourne un texte vide si rien n'est exploitable.
  return ''
}

// Récupère la première valeur disponible parmi plusieurs champs possibles.
function getFirstValue(object, names) {
  // Parcourt tous les noms possibles.
  for (const name of names) {
    // Récupère la valeur du champ courant.
    const value = toText(object?.[name])

    // Vérifie si la valeur existe.
    if (value) {
      // Retourne la première valeur trouvée.
      return value
    }
  }

  // Retourne un texte vide si rien n'est trouvé.
  return ''
}

// Décode un contenu Gmail encodé en base64url.
function decodeBase64Url(value) {
  // Vérifie si la valeur est vide.
  if (!value) {
    // Retourne un texte vide.
    return ''
  }

  // Remplace les caractères base64url par des caractères base64 classiques.
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/')

  // Décode le contenu base64.
  return Buffer.from(base64, 'base64').toString('utf8')
}

// Décode les entités HTML fréquentes.
function decodeHtmlEntities(value) {
  // Vérifie si la valeur est vide.
  if (!value) {
    // Retourne un texte vide.
    return ''
  }

  // Remplace les entités HTML par des caractères normaux.
  return value
    .replace(/&nbsp;/gi, ' ')
    .replace(/&zwnj;/gi, ' ')
    .replace(/&zwj;/gi, ' ')
    .replace(/&shy;/gi, ' ')
    .replace(/&#8204;/g, ' ')
    .replace(/&#8205;/g, ' ')
    .replace(/&#173;/g, ' ')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&eacute;/gi, 'é')
    .replace(/&egrave;/gi, 'è')
    .replace(/&ecirc;/gi, 'ê')
    .replace(/&agrave;/gi, 'à')
    .replace(/&ccedil;/gi, 'ç')
    .replace(/&ocirc;/gi, 'ô')
    .replace(/&ugrave;/gi, 'ù')
    .replace(/&#(\d+);/g, (match, number) => String.fromCharCode(Number(number)))
}

// Nettoie un contenu HTML pour obtenir un texte lisible.
function cleanHtml(value) {
  // Vérifie si la valeur est vide.
  if (!value) {
    // Retourne un texte vide.
    return ''
  }

  // Décode d'abord les entités HTML visibles comme &zwnj;.
  const decodedFirst = decodeHtmlEntities(value)

  // Supprime les scripts.
  const withoutScripts = decodedFirst.replace(/<script[\s\S]*?<\/script>/gi, ' ')

  // Supprime les styles.
  const withoutStyles = withoutScripts.replace(/<style[\s\S]*?<\/style>/gi, ' ')

  // Supprime les commentaires HTML.
  const withoutComments = withoutStyles.replace(/<!--[\s\S]*?-->/g, ' ')

  // Remplace certaines balises par des espaces pour éviter de coller les phrases.
  const withSpaces = withoutComments
    .replace(/<\/p>/gi, ' ')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<\/div>/gi, ' ')
    .replace(/<\/tr>/gi, ' ')
    .replace(/<\/td>/gi, ' ')
    .replace(/<\/li>/gi, ' ')

  // Supprime toutes les balises HTML restantes.
  const withoutTags = withSpaces.replace(/<[^>]*>/g, ' ')

  // Décode encore une fois les entités restantes.
  const decodedSecond = decodeHtmlEntities(withoutTags)

  // Supprime les vrais caractères invisibles Unicode.
  const withoutInvisible = decodedSecond.replace(/[\u200B-\u200D\uFEFF\u00AD]/g, ' ')

  // Supprime les répétitions inutiles de la mention image.
  const withoutTooManyImages = withoutInvisible.replace(/\[image:\s*[^\]]+\]/gi, ' ')

  // Remplace plusieurs espaces par un seul espace.
  const cleanText = withoutTooManyImages.replace(/\s+/g, ' ').trim()

  // Retourne le texte propre.
  return cleanText
}

// Nettoie le nom de l'expéditeur.
function cleanSender(value) {
  // Transforme la valeur en texte.
  const sender = toText(value)

  // Vérifie si l'expéditeur est vide.
  if (!sender) {
    // Retourne une valeur par défaut.
    return 'Expéditeur inconnu'
  }

  // Supprime les guillemets autour du nom de l'expéditeur.
  const cleaned = sender
    .replace(/^"([^"]+)"\s*</, '$1 <')
    .replace(/\\"/g, '"')
    .trim()

  // Retourne l'expéditeur nettoyé.
  return cleaned || 'Expéditeur inconnu'
}

// Récupère un header Gmail.
function getHeader(mail, headerName) {
  // Met le nom recherché en minuscules.
  const wantedName = headerName.toLowerCase()

  // Récupère les headers dans payload.headers.
  const payloadHeaders = mail.payload?.headers || []

  // Vérifie si payload.headers est un tableau.
  if (Array.isArray(payloadHeaders)) {
    // Cherche le header demandé.
    const foundHeader = payloadHeaders.find((header) => header.name?.toLowerCase() === wantedName)

    // Vérifie si le header existe.
    if (foundHeader?.value) {
      // Retourne la valeur du header.
      return foundHeader.value
    }
  }

  // Récupère les headers directs.
  const directHeaders = mail.headers || {}

  // Vérifie si headers est un tableau.
  if (Array.isArray(directHeaders)) {
    // Cherche le header demandé.
    const foundHeader = directHeaders.find((header) => header.name?.toLowerCase() === wantedName)

    // Vérifie si le header existe.
    if (foundHeader?.value) {
      // Retourne la valeur du header.
      return foundHeader.value
    }
  }

  // Vérifie si headers est un objet.
  if (typeof directHeaders === 'object' && directHeaders !== null) {
    // Cherche le header avec le nom exact.
    const exactValue = directHeaders[headerName]

    // Vérifie si la valeur exacte existe.
    if (exactValue) {
      // Retourne la valeur exacte.
      return toText(exactValue)
    }

    // Cherche le header avec le nom en minuscules.
    const lowerValue = directHeaders[wantedName]

    // Vérifie si la valeur en minuscules existe.
    if (lowerValue) {
      // Retourne la valeur en minuscules.
      return toText(lowerValue)
    }

    // Cherche une clé qui correspond au header demandé.
    const matchingKey = Object.keys(directHeaders).find((key) => key.toLowerCase() === wantedName)

    // Vérifie si une clé correspond.
    if (matchingKey) {
      // Retourne la valeur trouvée.
      return toText(directHeaders[matchingKey])
    }
  }

  // Retourne un texte vide si rien n'est trouvé.
  return ''
}

// Récupère l'expéditeur du mail.
function getSender(mail) {
  // Cherche l'expéditeur dans les champs directs.
  const directSender = getFirstValue(mail, [
    'from',
    'From',
    'sender',
    'Sender',
    'expediteur',
    'replyTo',
    'reply_to'
  ])

  // Vérifie si un expéditeur direct existe.
  if (directSender) {
    // Retourne l'expéditeur nettoyé.
    return cleanSender(directSender)
  }

  // Cherche l'expéditeur dans le header From.
  const fromHeader = getHeader(mail, 'From')

  // Vérifie si le header From existe.
  if (fromHeader) {
    // Retourne l'expéditeur nettoyé.
    return cleanSender(fromHeader)
  }

  // Cherche l'expéditeur dans le header Sender.
  const senderHeader = getHeader(mail, 'Sender')

  // Vérifie si le header Sender existe.
  if (senderHeader) {
    // Retourne l'expéditeur nettoyé.
    return cleanSender(senderHeader)
  }

  // Cherche l'expéditeur dans le header Reply-To.
  const replyToHeader = getHeader(mail, 'Reply-To')

  // Vérifie si Reply-To existe.
  if (replyToHeader) {
    // Retourne l'expéditeur nettoyé.
    return cleanSender(replyToHeader)
  }

  // Retourne une valeur par défaut.
  return 'Expéditeur inconnu'
}

// Récupère l'objet du mail.
function getSubject(mail) {
  // Cherche l'objet dans les champs directs.
  const directSubject = getFirstValue(mail, ['subject', 'Subject', 'objet'])

  // Vérifie si un objet direct existe.
  if (directSubject) {
    // Retourne l'objet direct.
    return cleanHtml(directSubject)
  }

  // Cherche l'objet dans les headers.
  const headerSubject = getHeader(mail, 'Subject')

  // Vérifie si un objet existe dans les headers.
  if (headerSubject) {
    // Retourne l'objet trouvé.
    return cleanHtml(headerSubject)
  }

  // Retourne une valeur par défaut.
  return 'Sans objet'
}

// Lit toutes les parties disponibles dans le payload Gmail.
function getBodyFromPayload(payload) {
  // Crée une liste pour les textes simples.
  const plainTexts = []

  // Crée une liste pour les contenus HTML.
  const htmlTexts = []

  // Crée une fonction interne pour parcourir le payload.
  function readPart(part) {
    // Vérifie si la partie existe.
    if (!part) {
      // Arrête la fonction.
      return
    }

    // Vérifie si cette partie contient des données.
    if (part.body?.data) {
      // Décode les données.
      const decoded = decodeBase64Url(part.body.data)

      // Vérifie si le contenu décodé existe.
      if (decoded) {
        // Vérifie si la partie est du texte simple.
        if (part.mimeType === 'text/plain') {
          // Ajoute le texte simple.
          plainTexts.push(decoded)
        } else {
          // Ajoute le contenu HTML ou général.
          htmlTexts.push(decoded)
        }
      }
    }

    // Récupère les sous-parties.
    const subParts = part.parts || []

    // Parcourt toutes les sous-parties.
    for (const subPart of subParts) {
      // Lit chaque sous-partie.
      readPart(subPart)
    }
  }

  // Lance la lecture du payload complet.
  readPart(payload)

  // Fusionne les textes simples.
  const plainContent = plainTexts.join(' ')

  // Fusionne les contenus HTML.
  const htmlContent = htmlTexts.join(' ')

  // Nettoie le texte simple.
  const cleanedPlain = cleanHtml(plainContent)

  // Nettoie le HTML.
  const cleanedHtml = cleanHtml(htmlContent)

  // Vérifie si le texte simple est plus complet.
  if (cleanedPlain.length >= cleanedHtml.length) {
    // Retourne le texte simple.
    return cleanedPlain
  }

  // Retourne le texte HTML nettoyé.
  return cleanedHtml
}

// Formate la date du mail.
function formatMailDate(mail) {
  // Récupère la date directe.
  const directDate = getFirstValue(mail, ['date', 'Date', 'receivedDate'])

  // Récupère la date depuis les headers.
  const headerDate = getHeader(mail, 'Date')

  // Récupère la date interne Gmail.
  const internalDate = mail.internalDate

  // Vérifie si internalDate existe et ressemble à un nombre.
  if (internalDate && !isNaN(Number(internalDate))) {
    // Transforme internalDate en date JavaScript.
    const date = new Date(Number(internalDate))

    // Vérifie si la date est valide.
    if (!isNaN(date.getTime())) {
      // Retourne la date en français.
      return date.toLocaleString('fr-FR')
    }
  }

  // Choisit la meilleure date texte disponible.
  const rawDate = directDate || headerDate

  // Vérifie si une date texte existe.
  if (rawDate) {
    // Transforme la date texte en date JavaScript.
    const date = new Date(rawDate)

    // Vérifie si la date est valide.
    if (!isNaN(date.getTime())) {
      // Retourne la date en français.
      return date.toLocaleString('fr-FR')
    }
  }

  // Retourne une valeur par défaut.
  return 'Date inconnue'
}

// Récupère le contenu complet du mail.
function getMailContent(mail) {
  // Récupère le texte direct.
  const directText = getFirstValue(mail, ['text', 'textPlain', 'plainText', 'bodyText', 'content'])

  // Récupère le HTML direct.
  const directHtml = getFirstValue(mail, ['html', 'textHtml', 'bodyHtml', 'htmlBody'])

  // Récupère le contenu document si n8n l'utilise.
  const documentContent = getFirstValue(mail, ['document'])

  // Récupère le contenu body si n8n l'utilise.
  const bodyContent = getFirstValue(mail, ['body'])

  // Récupère le contenu data si n8n l'utilise.
  const dataContent = getFirstValue(mail, ['data'])

  // Récupère le contenu depuis payload.
  const payloadContent = getBodyFromPayload(mail.payload)

  // Récupère le snippet Gmail.
  const snippet = getFirstValue(mail, ['snippet', 'preview'])

  // Prépare toutes les sources possibles.
  const sources = [
    directText,
    directHtml,
    documentContent,
    bodyContent,
    dataContent,
    payloadContent,
    snippet
  ]

  // Nettoie toutes les sources disponibles.
  const cleanedSources = sources.map((source) => cleanHtml(source)).filter(Boolean)

  // Vérifie si au moins une source existe.
  if (cleanedSources.length > 0) {
    // Trie les contenus du plus long au plus court.
    cleanedSources.sort((a, b) => b.length - a.length)

    // Retourne le contenu le plus long.
    return cleanedSources[0]
  }

  // Retourne une valeur par défaut.
  return 'Contenu non disponible.'
}

// Crée la date actuelle.
const now = new Date()

// Récupère l'année actuelle.
const year = now.getFullYear()

// Récupère le mois actuel avec deux chiffres.
const month = String(now.getMonth() + 1).padStart(2, '0')

// Récupère le jour actuel avec deux chiffres.
const day = String(now.getDate()).padStart(2, '0')

// Crée la date du jour au format React.
const today = `${year}-${month}-${day}`

// Garde seulement les éléments qui ressemblent à des e-mails.
const realItems = items.filter((item) => {
  // Récupère le mail courant.
  const mail = item.json

  // Vérifie si le mail contient des informations utiles.
  return mail.id || mail.messageId || mail.payload || mail.html || mail.text || mail.document || mail.snippet
})

// Transforme chaque mail Gmail en objet simple pour React.
const mails = realItems.map((item, index) => {
  // Récupère le mail courant.
  const mail = item.json

  // Récupère l'expéditeur.
  const expediteur = getSender(mail)

  // Récupère l'objet.
  const objet = getSubject(mail)

  // Récupère la date de réception.
  const dateReception = formatMailDate(mail)

  // Récupère le contenu complet.
  const contenu = getMailContent(mail)

  // Crée un résumé court pour la carte.
  const resume = contenu.length > 300 ? `${contenu.slice(0, 300)}...` : contenu

  // Retourne le mail dans le format attendu par React.
  return {
    // Identifiant simple pour React.
    id: index + 1,

    // Identifiant Gmail.
    messageId: mail.id || mail.messageId || '',

    // Identifiant du thread Gmail.
    threadId: mail.threadId || '',

    // Expéditeur du mail.
    expediteur: expediteur,

    // Objet du mail.
    objet: objet,

    // Date de réception.
    dateReception: dateReception,

    // Résumé court.
    resume: resume,

    // Contenu complet.
    contenu: contenu,

    // Statut de réponse.
    statut: 'non répondu'
  }
})

// Prépare le résumé global provisoire.
const resumeGlobal = `${mails.length} e-mail(s) reçu(s) aujourd’hui ont été récupéré(s) depuis Gmail.`

// Retourne les données finales à React.
return [
  {
    json: {
      date: today,
      resumeGlobal: resumeGlobal,
      mails: mails
    }
  }
]

// Récupère les données venant du nœud IF.
const data = $input.first().json

// Récupère la liste des messages.
const messages = data.messages || []

// Transforme chaque mail en ID propre pour le nœud Gmail suivant.
const preparedItems = messages.map((message) => {
  // Récupère l'ID Gmail du message.
  const messageId = String(message.id).trim()

  // Retourne un item propre.
  return {
    json: {
      id: messageId,
      messageId: messageId,
      threadId: message.threadId || ''
    }
  }
})

// Retourne les IDs au nœud suivant.
return preparedItems

// Récupère les données préparées pour React.
const data = $input.first().json

// Récupère la liste des mails.
const mails = data.mails || []

// Transforme chaque mail en texte simple pour Groq.
const mailsText = mails.map((mail, index) => {
  // Retourne un bloc lisible pour chaque mail.
  return `
Mail ${index + 1}
Expéditeur : ${mail.expediteur}
Objet : ${mail.objet}
Date : ${mail.dateReception}
Résumé court : ${mail.resume}
Contenu : ${mail.contenu}
`
}).join('\n--------------------\n')

// Prépare la consigne envoyée à Groq.
const prompt = `
Tu dois analyser les e-mails reçus aujourd'hui et produire un résumé global clair.

Réponds exactement avec cette structure :

Résumé général :
Écris ici un court paragraphe qui résume la journée.

Points importants :
- Point important 1
- Point important 2
- Point important 3

Actions à faire :
- Action 1 s'il y en a une
- Sinon écris : Aucune action urgente détectée.

Contraintes :
- Réponds uniquement en français.
- Ne répète pas tous les mails un par un.
- Ne mets pas de Markdown avec des astérisques.
- Ne mets pas de texte comme **Mail 1**.
- Fais une réponse claire, courte et facile à lire.

Voici les e-mails reçus aujourd'hui :

${mailsText}
` 

// Retourne les données originales avec le prompt ajouté.
return [
  {
    json: {
      date: data.date,
      resumeGlobal: data.resumeGlobal,
      mails: data.mails,
      prompt: prompt
    }
  }
]

// Récupère la réponse du nœud Basic LLM Chain.
const aiResponse = $input.first().json

// Récupère les données originales préparées avant Groq.
const originalData = $('Préparer la demande Groq').first().json

// Essaie de récupérer le résumé dans plusieurs champs possibles.
const generatedSummary =
  aiResponse.text ||
  aiResponse.output ||
  aiResponse.response ||
  aiResponse.result ||
  aiResponse.content ||
  aiResponse.answer ||
  aiResponse.message ||
  ''

// Vérifie si Groq a vraiment généré un résumé.
const finalSummary = generatedSummary || originalData.resumeGlobal

// Retourne le JSON final attendu par React.
return [
  {
    json: {
      date: originalData.date,
      resumeGlobal: finalSummary,
      mails: originalData.mails
    }
  }
]

// Récupère tous les éléments reçus depuis le nœud Gmail précédent.
const items = $input.all()

// Crée une date avec la date actuelle.
const now = new Date()

// Récupère l'année actuelle.
const year = now.getFullYear()

// Récupère le mois actuel avec deux chiffres.
const month = String(now.getMonth() + 1).padStart(2, '0')

// Récupère le jour actuel avec deux chiffres.
const day = String(now.getDate()).padStart(2, '0')

// Crée la date du jour au format attendu par React.
const today = `${year}-${month}-${day}`

// Crée une liste vide pour stocker les vrais mails trouvés.
const messages = []

// Parcourt tous les éléments reçus.
for (const item of items) {
  // Récupère les données JSON de l'élément actuel.
  const data = item.json || {}

  // Vérifie si l'élément contient directement un vrai identifiant Gmail.
  if (data.id) {
    // Ajoute ce mail dans la liste.
    messages.push(data)
  }

  // Vérifie si l'élément contient une liste de messages.
  if (Array.isArray(data.messages)) {
    // Ajoute tous les messages trouvés.
    messages.push(...data.messages)
  }

  // Vérifie si l'élément contient une liste data.
  if (Array.isArray(data.data)) {
    // Ajoute tous les éléments trouvés.
    messages.push(...data.data)
  }

  // Vérifie si l'élément contient une liste items.
  if (Array.isArray(data.items)) {
    // Ajoute tous les éléments trouvés.
    messages.push(...data.items)
  }
}

// Garde uniquement les messages qui ont un ID Gmail correct.
const validMessages = messages.filter((message) => {
  // Récupère l'identifiant du message.
  const id = message.id

  // Refuse si l'identifiant est absent.
  if (!id) {
    return false
  }

  // Transforme l'identifiant en texte.
  const cleanId = String(id).trim()

  // Refuse les identifiants vides.
  if (!cleanId) {
    return false
  }

  // Refuse les valeurs invalides.
  if (cleanId === 'undefined' || cleanId === 'null' || cleanId.includes('{{')) {
    return false
  }

  // Accepte le message.
  return true
})

// Retourne une seule sortie claire pour le nœud IF.
return [
  {
    json: {
      date: today,
      mailCount: validMessages.length,
      messages: validMessages,
      resumeGlobal: validMessages.length === 0
        ? "Aucun e-mail reçu aujourd’hui. Vous n’avez aucune action à traiter pour le moment."
        : `${validMessages.length} e-mail(s) reçu(s) aujourd’hui ont été récupéré(s) depuis Gmail.`,
      mails: []
    }
  }
]

